import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    if n <= 2: print(0); sys.exit(0)
    primes = bytearray([1]) * n
    primes[0] = primes[1] = 0
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            primes[p*p:n:p] = bytes(len(range(p*p, n, p)))
    print(sum(primes))
